import sys

RADIX=255

class Enc:
    def __init__(self):
        self.low=0
        self.range=1
        self.M=0
        self.cc={}
    def cnt(self,ctx):
        v=self.cc.get(ctx)
        if v is None:
            v=[0,0]; self.cc[ctx]=v
        return v
    def emit(self,ctx,bit):
        if self.range<RADIX:
            self.range*=RADIX
            self.low*=RADIX
            self.M+=1
        c=self.cnt(ctx)
        c0,c1=c[0],c[1]
        split=self.range*(c0+1)//(c0+c1+2)
        if bit:
            assert split<self.range
            self.low+=split
            self.range-=split
        else:
            assert split>0, "unrepresentable 0 bit"
            self.range=split
        c[bit]+=1
    def integer(self,V,t,ctxbase):
        cb=ctxbase*99
        result=V+(1<<t)
        m=result.bit_length()-1
        # unary zeros for tmp=t+1..m, then 1 at m+1
        for tmp in range(t+1,m+1):
            self.emit(tmp+cb,0)
        self.emit((m+1)+cb,1)
        for i in range(m-1,-1,-1):
            self.emit(cb,(result>>i)&1)
    def finish(self):
        digits=[]
        tmp=self.low
        for _ in range(self.M):
            digits.append(tmp%RADIX); tmp//=RADIX
        assert tmp==0, "low too big"
        digits=digits[::-1]
        return bytes([d+1 for d in digits])

def literal(enc,byte,order):
    # signed char value
    sv = byte if byte<128 else byte-256
    sign = 1 if sv<0 else 0
    mag = -sv if sv<0 else sv
    if order==0:
        enc.emit(8,sign)
        enc.integer(mag,4,9)
    else:
        enc.integer(mag,4,9)
        enc.emit(8,sign)

def build(tokens,order):
    enc=Enc()
    enc.integer(len(tokens),9,0)
    for tk in tokens:
        if tk[0]=='L':
            enc.emit(1,0)
            literal(enc,tk[1],order)
        else:
            _,d,length=tk
            enc.emit(1,1)
            enc.integer(d,5,2)
            enc.integer(length-1,2,3)
    return enc.finish()

# ---- test round trip via /app/decomp
import subprocess
def decomp(data):
    p=subprocess.run(['/app/decomp'],input=data,stdout=subprocess.PIPE)
    return p.stdout

if __name__=='__main__':
    mode=sys.argv[1] if len(sys.argv)>1 else 'test'
    if mode=='test':
        s=b"Hello, world! This is a test.\x00"
        # all literal tokens, no trailing extra (null included in string end)
        for order in (0,1):
            toks=[('L',b) for b in s]
            comp=build(toks,order)
            out=decomp(comp)
            print("order",order,"complen",len(comp),"match", out==b"Hello, world! This is a test.")
