def parse(data, minlen, maxcand=64):
    n=len(data)
    tokens=[]
    table={}
    i=0
    while i<n:
        best_len=0; best_d=0
        key=data[i:i+3]
        if len(key)==3:
            cands=table.get(key)
            if cands:
                for j in reversed(cands[-maxcand:]):
                    l=0
                    maxl=n-i
                    while l<maxl and data[j+l]==data[i+l]:
                        l+=1
                    if l>best_len:
                        best_len=l; best_d=i-j-1
        if best_len>=minlen:
            tokens.append(('M',best_d,best_len))
            end=i+best_len
            while i<end:
                if i+3<=n:
                    table.setdefault(data[i:i+3],[]).append(i)
                i+=1
        else:
            tokens.append(('L',data[i]))
            if i+3<=n:
                table.setdefault(data[i:i+3],[]).append(i)
            i+=1
    return tokens

def run():
    data=open('data.txt','rb').read()
    best=None
    for minlen in range(3,9):
        toks=parse(data,minlen)
        toks=toks+[('L',0)]
        comp=build(toks,0)
        if best is None or len(comp)<len(best[1]):
            best=(minlen,comp,toks)
    minlen,comp,toks=best
    out=decomp(comp)
    ok = out==data
    print("minlen",minlen,"complen",len(comp),"ok",ok)
    open('data.comp','wb').write(comp)
    return ok,len(comp)

if __name__=='__main__' and len(sys.argv)>1 and sys.argv[1]=='run':
    run()
