data=open('data.txt','rb').read()
n=len(data)

def longest(table,i,maxcand):
    key=data[i:i+3]
    best_len=0;best_d=0
    if len(key)==3:
        cands=table.get(key)
        if cands:
            for j in reversed(cands if maxcand is None else cands[-maxcand:]):
                l=0;maxl=n-i
                while l<maxl and data[j+l]==data[i+l]:l+=1
                if l>best_len:best_len=l;best_d=i-j-1
    return best_len,best_d

def parse_lazy(minlen,maxcand=None):
    table={};i=0;tokens=[]
    def add(p):
        if p+3<=n: table.setdefault(data[p:p+3],[]).append(p)
    while i<n:
        l1,d1=longest(table,i,maxcand)
        if l1>=minlen:
            # lazy: check i+1
            add(i)
            l2,d2=longest(table,i+1,maxcand)
            if l2>l1+1:
                tokens.append(('L',data[i]))
                i+=1
                continue
            tokens.append(('M',d1,l1))
            end=i+l1
            i+=1
            while i<end:
                add(i);i+=1
        else:
            tokens.append(('L',data[i]));add(i);i+=1
    return tokens

